(function () {
// Embedded PDFs keep Save working in exported folders opened directly, without a server.
var diaryPDFs = {"som-plant-diary.pdf":"","som-plant-diary-en.pdf":""};
document.addEventListener('DOMContentLoaded', function () {
  var modal = document.getElementById('diary-language-modal');
  if (!modal) return;
  var status = document.createElement('p');
  status.setAttribute('role', 'status'); status.setAttribute('aria-live', 'polite');
  status.style.cssText = 'margin:16px 0 0;text-align:center;font-size:.85rem';
  modal.querySelector('.modal-body').appendChild(status);
  modal.querySelectorAll('a[download]').forEach(function (link) {
    link.removeAttribute('target');
    link.addEventListener('click', function (event) {
      event.preventDefault();
      try {
        var filename = link.getAttribute('download');
        var encoded = diaryPDFs[filename];
        if (!encoded) throw new Error('Diary unavailable');
        var decoded = atob(encoded);
        var bytes = new Uint8Array(decoded.length);
        for (var i = 0; i < decoded.length; i++) bytes[i] = decoded.charCodeAt(i);
        var blob = new Blob([bytes], { type: 'application/octet-stream' });
        var objectUrl = URL.createObjectURL(blob);
        var save = document.createElement('a');
        save.href = objectUrl; save.download = filename; save.style.display = 'none';
        document.body.appendChild(save); save.click(); save.remove();
        setTimeout(function () { URL.revokeObjectURL(objectUrl); }, 60000);
        status.textContent = '';
        document.dispatchEvent(new CustomEvent('som:diary-download-started'));
        if (window.bootstrap && window.bootstrap.Modal) { var instance = window.bootstrap.Modal.getInstance(modal); if (instance) instance.hide(); }
      } catch (_) { status.textContent = 'The diary could not be saved. Please try again.'; }
    });
  });
});
})();
